/// <summary>
/// Extension for VendorInvoiceLineSourceDocLineItem to handle catchweight amount calculation.
/// </summary>
[ExtensionOf(classStr(VendorInvoiceLineSourceDocLineItem))]
final class METVendorInvoiceLineSourceDocLineItem_Extension
{
}

Method.Source:
/// <summary>
///     Calculates the actual gross amount for purchase price.
/// </summary>
/// <returns>
///     The actual gross amount.
/// </returns>
protected Amount calculateActualGrossAmountForPurchPrice()
{
    Amount amount = next calculateActualGrossAmountForPurchPrice();

    VendInvoiceInfoLine vendInvoiceInfoLine = VendInvoiceInfoLine::findSourceDocumentLine(this.parmSourceDocumentLine().RecId);

    if (!vendInvoiceInfoLine.RecId || !PdsGlobal::pdsIsCWItem(vendInvoiceInfoLine.ItemId))
    {
        return amount;
    }

    return CurrencyExchangeHelper::amount(vendInvoiceInfoLine.METInvoiceRWQuantity * vendInvoiceInfoLine.PurchPrice, vendInvoiceLineMap.CurrencyCode);
}
